static void prism54_clear_mac ( struct islpci_acl * acl ) { struct list_head * ptr , * next ; struct mac_entry * entry ; mutex_lock ( & acl -> lock ) ; if ( acl -> size == 0 ) { mutex_unlock ( & acl -> lock ) ; return ; } for ( ptr = acl -> mac_list . next , next = ptr -> next ; ptr != & acl -> mac_list ; ptr = next , next = ptr -> next ) { entry = list_entry ( ptr , mac_entry , _list ) ; list_del ( ptr , NULL ) ; kfree ( entry ) ; } acl -> size = 0 ; mutex_unlock ( & acl -> lock ) ; } 